def register(request):
    if request.method == "POST":
        form = RegistrationForm(request.POST)
        if form.is_valid():
            user = form.save()
            Profile.objects.create(user=user, role=Profile.ROLE_STUDENT)
            audit(user, "user.registered", user, "Student self-registration completed", request)
            login(request, user)
            messages.success(request, "Account created. You can now enroll in available courses.")
            return redirect("dashboard")

